/**
 * Node tests for the two-phone TX/RX link helpers (slice 1.8).
 *
 * The receiver test is end-to-end at the sample level: frames are generated by
 * the real encoder, cut into worklet-sized chunks, passed through the rolling
 * buffer and recovered by the real decoder. No hardware is involved.
 */
const test = require("node:test");
const assert = require("node:assert/strict");
const fsk = require("./fsk");
const link = require("./transmitPlan");
const receiver = require("./receiver");

const CHUNK = 4096;
const SAMPLE_RATE = 48000;

const concat = (parts) => {
  const total = parts.reduce((sum, part) => sum + part.length, 0);
  const output = new Float32Array(total);
  let offset = 0;
  for (const part of parts) {
    output.set(part, offset);
    offset += part.length;
  }
  return output;
};

const silence = (seconds) => new Float32Array(Math.round(SAMPLE_RATE * seconds));

test("run IDs are short, unambiguous and validated", () => {
  const values = [0, 0.1, 0.5, 0.99];
  let index = 0;
  const id = link.generateRunId(() => values[index++ % values.length]);
  assert.equal(id.length, 6);
  assert.match(id, /^[A-HJ-NP-Z2-9]{6}$/);
  assert.equal(link.normaliseRunId(` ${id.toLowerCase()} `), id);
  assert.equal(link.validateRunId(id), true);
  assert.equal(link.validateRunId("ABC"), false);
  assert.equal(link.validateRunId("HAS SPACE"), false);
  assert.equal(link.validateRunId("O0I1"), false);
});

test("receiver link carries the run ID and the transmitter conditions", () => {
  const search = link.buildReceiverSearch("ab12cd", {
    distance: "5 m",
    room: "Room A",
    notes: "M01 TX, volume 60%",
  });
  const params = new URLSearchParams(search);
  assert.equal(params.get("run"), "AB12CD");
  assert.equal(params.get("distance"), "5 m");
  assert.equal(params.get("room"), "Room A");
  assert.equal(params.get("notes"), "M01 TX, volume 60%");

  assert.deepEqual(link.readReceiverConditions(`?${search}`), {
    distance: "5 m",
    room: "Room A",
    notes: "M01 TX, volume 60%",
  });

  assert.equal(link.buildReceiverSearch("AB12CD"), "run=AB12CD");
  assert.deepEqual(link.readReceiverConditions(""), {});
  assert.deepEqual(link.readReceiverConditions("?run=AB12CD&distance=%20%20"), {});
  assert.deepEqual(link.readReceiverConditions("?run=AB12CD&room=Lab&notes="), { room: "Lab" });
});

test("check-in launch links prefill only a valid transmitter key", () => {
  assert.equal(link.buildTransmitSearch(42, "checkin"), "key=42&from=checkin");
  assert.equal(link.buildTransmitSearch(0), "key=0");
  assert.equal(link.readTransmitKey("?key=42&from=checkin"), 42);
  assert.equal(link.readTransmitKey("?key=0"), 0);
  assert.equal(link.readTransmitKey(`?key=${link.MAX_KEY_VALUE}`), link.MAX_KEY_VALUE);

  for (const bad of [
    "",
    "?key=",
    "?key=-1",
    `?key=${link.MAX_KEY_VALUE + 1}`,
    "?key=abc",
    "?key=1.5",
    "?key=1e2",
    "?key=0x10",
    "?key=%2B42",
    "?from=checkin",
  ]) {
    assert.equal(link.readTransmitKey(bad), null, `${bad} must not prefill a key`);
  }

  assert.throws(() => link.buildTransmitSearch(-1), /key must be an integer/);
  assert.throws(() => link.buildTransmitSearch(link.MAX_KEY_VALUE + 1), /key must be an integer/);
});

test("TX reports normalise a string amplitude from the range input", () => {
  const plan = link.buildTransmissionPlan({ key: 42, repeats: 2, gapMs: 450 });
  const json = link.buildTxReportJson({ runId: "ABC234", plan, amplitude: "0.9" });
  assert.equal(json.amplitude, 0.9);

  const text = link.formatTxReport({ runId: "ABC234", plan, amplitude: "0.9" });
  assert.match(text, /Amplitude setting: 0.9/);
});

test("key, repeats and gap validation cover both boundaries", () => {
  assert.equal(link.validateKey(0), true);
  assert.equal(link.validateKey(link.MAX_KEY_VALUE), true);
  assert.equal(link.validateKey(link.MAX_KEY_VALUE + 1), false);
  assert.equal(link.validateKey(1.5), false);
  assert.equal(link.validateKey(-1), false);
  assert.equal(link.validateRepeats(1), true);
  assert.equal(link.validateRepeats(link.MAX_REPEATS), true);
  assert.equal(link.validateRepeats(0), false);
  assert.equal(link.validateRepeats(101), false);
  assert.equal(link.validateGapMs(100), true);
  assert.equal(link.validateGapMs(5000), true);
  assert.equal(link.validateGapMs(99), false);
  assert.equal(link.validateAmplitude(0.01), true);
  assert.equal(link.validateAmplitude(1), true);
  assert.equal(link.validateAmplitude(0), false);
  assert.equal(link.validateAmplitude(1.1), false);
});

test("transmission plan has non-overlapping frames and an exact total duration", () => {
  const plan = link.buildTransmissionPlan({ key: 12345678, repeats: 3, gapMs: 400 });
  assert.equal(plan.frameDurationMs, 1320);
  assert.equal(plan.slotMs, 1720);
  assert.equal(plan.totalDurationMs, 4760);
  assert.deepEqual(
    plan.frames.map((frame) => [frame.startMs, frame.endMs]),
    [
      [0, 1320],
      [1720, 3040],
      [3440, 4760],
    ]
  );
  assert.equal(plan.dataDigits.length, fsk.DATA_SYMBOL_COUNT);
  assert.equal(plan.toneSequence.length, fsk.SYMBOL_COUNT);
  assert.deepEqual(plan.toneSequence, fsk.frameTones(fsk.valueToDigits(12345678)));
});

test("played-frame counter advances at the start of each frame", () => {
  const plan = link.buildTransmissionPlan({ key: 1, repeats: 3, gapMs: 400 });
  assert.equal(link.countStartedFrames(plan, -1), 0);
  assert.equal(link.countStartedFrames(plan, 0), 1);
  assert.equal(link.countStartedFrames(plan, 1319), 1);
  assert.equal(link.countStartedFrames(plan, 1720), 2);
  assert.equal(link.countStartedFrames(plan, 3440), 3);
  assert.equal(link.countStartedFrames(plan, 99999), 3);
  assert.equal(link.countStartedFrames(null, 100), 0);
});

test("decode rate is honest about missing or extra data", () => {
  assert.equal(link.decodeRate(9, 10), 0.9);
  assert.equal(link.decodeRate(0, 10), 0);
  assert.equal(link.decodeRate(null, 10), null);
  assert.equal(link.decodeRate(10, 0), null);
  assert.equal(link.formatPercent(0.95), "95.0%");
  assert.equal(link.formatPercent(null), "not available");
});

test("TX report states the plan and never claims the receiver heard it", () => {
  const plan = link.buildTransmissionPlan({ key: 42, repeats: 2, gapMs: 450 });
  const text = link.formatTxReport({
    generatedAt: new Date("2026-10-23T10:00:00Z"),
    runId: "ABC234",
    plan,
    played: 2,
    amplitude: 0.5,
    distance: "1 m",
    room: "Room A",
    device: { role: "tx", contextSampleRate: 48000, userAgent: "TestPhone" },
  });

  assert.match(text, /Run ID: ABC234/);
  assert.match(text, /Key value: 42/);
  assert.match(text, /Planned frames: 2/);
  assert.match(text, /Frames played: 2/);
  assert.match(text, /TX cannot know whether the receiver heard anything/);
  assert.equal(/attendance was marked/i.test(text), false);
});

test("RX report computes the decode rate and labels missing counts", () => {
  const text = link.formatRxReport({
    generatedAt: new Date("2026-10-23T10:00:00Z"),
    runId: "ABC234",
    planned: 10,
    decoded: 9,
    elapsedMs: 15000,
    lastKey: 42,
    lastMargin: 14.2,
    keys: [42, 42],
    device: { role: "rx", contextSampleRate: 48000, trackSampleRate: 48000, userAgent: "TestPhone" },
  });

  assert.match(text, /Decode rate: 90.0%/);
  assert.match(text, /Frames decoded: 9/);
  assert.match(text, /Last decoded key: 42/);
  assert.match(text, /does not prove which phone produced the sound/);

  const missing = link.formatRxReport({ runId: "ABC234", planned: 0, decoded: 0 });
  assert.match(missing, /not available \(set planned frames\)/);
});

test("JSON reports contain counts, conditions and no identity fields", () => {
  const tx = link.buildTxReportJson({
    runId: "abc234",
    plan: link.buildTransmissionPlan({ key: 7, repeats: 2, gapMs: 450 }),
    played: 2,
    amplitude: 0.5,
    distance: "1 m",
  });
  assert.equal(tx.runId, "ABC234");
  assert.equal(tx.role, "tx");
  assert.equal(tx.testType, "cross-phone");
  assert.equal(tx.played, 2);
  assert.equal(tx.conditions.distance, "1 m");

  const rx = link.buildRxReportJson({
    runId: "abc234",
    planned: 2,
    decoded: 2,
    keys: [7, 7],
    lastKey: 7,
  });
  assert.equal(rx.decodeRate, 1);
  assert.equal(rx.role, "rx");
  assert.equal(JSON.stringify(rx).includes("@"), false);
});

test("PCM buffer keeps absolute positions and drops consumed audio", () => {
  const buffer = receiver.createPcmBuffer();
  buffer.append(Float32Array.from([1, 2, 3]));
  buffer.append(Float32Array.from([4, 5]));
  assert.equal(buffer.totalSamples(), 5);
  assert.equal(buffer.startSample, 0);
  assert.equal(buffer.endSample, 5);

  const last = buffer.readLast(3);
  assert.deepEqual(Array.from(last.samples), [3, 4, 5]);
  assert.equal(last.startSample, 2);

  buffer.dropBefore(2);
  assert.equal(buffer.totalSamples(), 3);
  assert.deepEqual(Array.from(buffer.readLast(10).samples), [3, 4, 5]);

  buffer.dropBefore(4);
  assert.equal(buffer.totalSamples(), 1);
  assert.deepEqual(Array.from(buffer.readLast(10).samples), [5]);

  buffer.append(Float32Array.from([6, 7]));
  assert.equal(buffer.endSample, 7);
  assert.deepEqual(Array.from(buffer.readLast(10).samples), [5, 6, 7]);

  buffer.trimTo(2);
  assert.deepEqual(Array.from(buffer.readLast(10).samples), [6, 7]);
  buffer.reset();
  assert.equal(buffer.totalSamples(), 0);
});

test("end-to-end: chunked synthetic frames decode once each through the rolling buffer", () => {
  const digits = fsk.valueToDigits(9876543);
  const frame = fsk.encodeFrame(digits, SAMPLE_RATE, { amplitude: 0.35 });
  const gap = silence(0.45);
  const stream = concat([frame.samples, gap, frame.samples, gap, frame.samples]);

  const buffer = receiver.createPcmBuffer();
  const decoded = [];
  let chunkIndex = 0;
  for (let offset = 0; offset < stream.length; offset += CHUNK) {
    buffer.append(stream.subarray(offset, Math.min(stream.length, offset + CHUNK)));
    chunkIndex += 1;
    // Decode about twice a second, like the RX page; scanning on every 4096
    // sample chunk would be needlessly expensive without finding frames sooner.
    if (chunkIndex % 6 !== 0 && offset + CHUNK < stream.length) continue;
    let next = receiver.extractNextFrame(buffer, { sampleRate: SAMPLE_RATE });
    while (next) {
      decoded.push(next);
      next = receiver.extractNextFrame(buffer, { sampleRate: SAMPLE_RATE });
    }
  }

  // Drain the final frame after the last chunk.
  let next = receiver.extractNextFrame(buffer, { sampleRate: SAMPLE_RATE });
  while (next) {
    decoded.push(next);
    next = receiver.extractNextFrame(buffer, { sampleRate: SAMPLE_RATE });
  }

  assert.equal(decoded.length, 3);
  for (const result of decoded) {
    assert.equal(fsk.digitsToValue(result.dataDigits), 9876543);
    assert.ok(result.margin >= fsk.DEFAULT_DETECTION_MARGIN_DB);
    assert.ok(result.frameEndSample > result.frameStartSample);
  }
  assert.ok(decoded[0].frameStartSample < decoded[1].frameStartSample);
  assert.ok(decoded[1].frameStartSample < decoded[2].frameStartSample);
});

test("end-to-end: a partial frame never decodes", () => {
  const frame = fsk.encodeFrame(fsk.valueToDigits(123), SAMPLE_RATE, { amplitude: 0.35 });
  const buffer = receiver.createPcmBuffer();
  buffer.append(frame.samples.subarray(0, Math.round(frame.samples.length * 0.6)));
  assert.equal(receiver.extractNextFrame(buffer, { sampleRate: SAMPLE_RATE }), null);
});

test("end-to-end: noise does not produce a false frame", () => {
  let seed = 7;
  const random = () => {
    seed = (seed * 48271) % 2147483647;
    return seed / 2147483647;
  };
  const noise = new Float32Array(SAMPLE_RATE * 2);
  for (let index = 0; index < noise.length; index += 1) {
    noise[index] = (random() * 2 - 1) * 0.25;
  }

  const buffer = receiver.createPcmBuffer();
  buffer.append(noise);
  assert.equal(receiver.extractNextFrame(buffer, { sampleRate: SAMPLE_RATE }), null);
});
